function mkSpecTable(title, rows, name){
  const c = figma.createComponent(); c.name=name;
  c.resize(528,10);
  c.layoutMode='VERTICAL'; c.primaryAxisSizingMode='AUTO'; c.counterAxisSizingMode='FIXED';
  c.itemSpacing=0; c.fills=[];
  for(const [k,v] of rows){
    const row = figma.createFrame(); row.name='row';
    row.layoutMode='HORIZONTAL'; row.primaryAxisSizingMode='FIXED'; row.counterAxisSizingMode='AUTO';
    row.resize(528,44);
    row.paddingTop=12; row.paddingBottom=12;
    row.primaryAxisAlignItems='SPACE_BETWEEN'; row.counterAxisAlignItems='CENTER';
    row.fills=[];
    row.strokes=[solid(C.border)]; row.strokeWeight=1; row.strokeBottomWeight=1; row.strokeTopWeight=0; row.strokeLeftWeight=0; row.strokeRightWeight=0;
    row.appendChild(mkText(k,14,'Regular',C.mut));
    const vt = mkText(v,14,'Regular',C.ink,{w:320,lineHeight:20,align:'RIGHT'});
    row.appendChild(vt);
    c.appendChild(row);
  }
  return c;
}
