function mkReview(avatarHash, nm, photos, name){
  const c = figma.createComponent(); c.name=name;
  c.resize(608,10);
  c.layoutMode='VERTICAL'; c.primaryAxisSizingMode='AUTO'; c.counterAxisSizingMode='FIXED';
  c.itemSpacing=12; c.fills=[];
  const head = figma.createFrame(); head.name='head';
  head.layoutMode='HORIZONTAL'; head.primaryAxisSizingMode='FIXED'; head.counterAxisSizingMode='AUTO';
  head.resize(608,10);
  head.primaryAxisAlignItems='SPACE_BETWEEN'; head.counterAxisAlignItems='CENTER';
  head.fills=[]; head.counterAxisSizingMode='AUTO';
  const who = figma.createFrame(); who.name='who';
  who.layoutMode='HORIZONTAL'; who.itemSpacing=12; who.counterAxisAlignItems='CENTER';
  who.primaryAxisSizingMode='AUTO'; who.counterAxisSizingMode='AUTO'; who.fills=[];
  const av = figma.createRectangle(); av.resize(48,48); av.cornerRadius=999;
  av.fills=[{type:'IMAGE', imageHash:avatarHash, scaleMode:'FILL'}]; av.name='avatar';
  who.appendChild(av);
  const wc = figma.createFrame(); wc.layoutMode='VERTICAL'; wc.itemSpacing=2;
  wc.primaryAxisSizingMode='AUTO'; wc.counterAxisSizingMode='AUTO'; wc.fills=[];
  const nmt = mkText(nm,16,'Medium',C.ink); nmt.name='name';
  wc.appendChild(nmt);
  wc.appendChild(mkText('24 January 2023',12,'Regular',C.mut));
  who.appendChild(wc);
  head.appendChild(who);
  const sr = figma.createFrame(); sr.name='stars';
  sr.layoutMode='HORIZONTAL'; sr.itemSpacing=2;
  sr.primaryAxisSizingMode='AUTO'; sr.counterAxisSizingMode='AUTO'; sr.fills=[];
  for(let i=0;i<4;i++) sr.appendChild(figma.getNodeById('7:4').createInstance());
  sr.appendChild(figma.getNodeById('7:5').createInstance());
  head.appendChild(sr);
  c.appendChild(head);
  const body = mkText('',14,'Regular',C.sec,{w:608,lineHeight:22});
  body.name='text';
  c.appendChild(body);
  if(photos){
    const pr = figma.createFrame(); pr.name='review-photos';
    pr.layoutMode='HORIZONTAL'; pr.itemSpacing=12;
    pr.primaryAxisSizingMode='AUTO'; pr.counterAxisSizingMode='AUTO'; pr.fills=[];
    for(const h of photos){
      const r = figma.createRectangle(); r.resize(80,80); r.cornerRadius=8;
      r.fills=[{type:'IMAGE', imageHash:h, scaleMode:'FILL'}];
      pr.appendChild(r);
    }
    c.appendChild(pr);
  }
  return c;
}
