    const chip = variant('7:60','Type='+ty).createInstance();
    chip.resize(205,60);
    if(ty==='Screen'){
      const colF = chip.findOne(n=>n.type==='FRAME' && n.layoutMode==='VERTICAL');
      colF.children[0].characters=lbl;
      colF.children[1].characters=val;
    } else {
      chip.children[0].characters=lbl;
      chip.children[1].characters=val;
    }
    chip.name='chip-'+lbl;
    row.appendChild(chip);
  }
  chipGrid.appendChild(row);
}
buy.appendChild(chipGrid);

// delivery badges
const badgeRow = figma.createFrame(); badgeRow.name='badges';
badgeRow.layoutMode='HORIZONTAL'; badgeRow.itemSpacing=12;
badgeRow.primaryAxisSizingMode='AUTO'; badgeRow.counterAxisSizingMode='AUTO'; badgeRow.fills=[];
for(const ty of ['Delivery','Stock','Guarantee']){
  const b = variant('7:84','Type='+ty).createInstance();
  b.resize(205,88);
  badgeRow.appendChild(b);
}
buy.appendChild(badgeRow);

// actions
const actRow = figma.createFrame(); actRow.name='actions';
actRow.layoutMode='HORIZONTAL'; actRow.itemSpacing=16;
actRow.primaryAxisSizingMode='AUTO'; actRow.counterAxisSizingMode='AUTO'; actRow.fills=[];
const wish = variant('12:27','State=Secondary').createInstance();
wish.resize(304,56); wish.name='add-to-wishlist';
wish.children[0].characters='Add to Wishlist';
actRow.appendChild(wish);
const addCart = variant('12:27','State=Primary').createInstance();
addCart.resize(304,56); addCart.name='add-to-cart';
addCart.children[0].characters='Add to Cart';
actRow.appendChild(addCart);
buy.appendChild(actRow);

main.appendChild(buy);
frame.appendChild(main);

return 'OK 03 main [' + frame.id + '] h=' + Math.round(frame.height) + ' buy h=' + Math.round(buy.height) + ' gal h=' + Math.round(gal.height);
